import { test } from 'node:test';
import assert from 'node:assert/strict';
import { exportNames, handleExport } from '../src/server.js';

// CONTRIBUTING.md: the only export a guest may see is the holiday calendar.
// Every other registered export must stop anyone outside the team (#14, #15).
// A new export is checked here as soon as it is registered in src/server.js;
// add it to this list only when the team has decided that guests may see it.
const GUEST_VISIBLE = ['holidays'];

const FORBIDDEN = { status: 403, body: { error: 'forbidden' } };

for (const name of exportNames().filter((n) => !GUEST_VISIBLE.includes(n))) {
  test(`the ${name} export is for the team only`, () => {
    assert.deepEqual(handleExport(name, { role: 'guest' }), FORBIDDEN, 'guest');
    assert.deepEqual(handleExport(name, {}), FORBIDDEN, 'no role');
    assert.equal(handleExport(name, { role: 'admin' }).status, 200, 'admin');
    assert.equal(handleExport(name, { role: 'member' }).status, 200, 'member');
  });
}

for (const name of GUEST_VISIBLE) {
  test(`the ${name} export is open to a guest`, () => {
    assert.ok(exportNames().includes(name), `${name} is not a registered export`);
    assert.equal(handleExport(name, { role: 'guest' }).status, 200);
  });
}

